"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["22954"],{10904(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.hipotese_legal_incompativel_com_classificacao","status":422,"titulo":"A hip\xf3tese legal n\xe3o cabe na classifica\xe7\xe3o de prote\xe7\xe3o do fato"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.hipotese_legal_incompativel_com_classificacao","requisitos":["UNI-REQ-0143","UNI-REQ-0205"],"oQueAconteceu":["A hip\xf3tese legal \xe9 a base da LGPD que autoriza o tratamento do dado, e o artigo dela depende da classifica\xe7\xe3o (UNI-REQ-0205). O dado sens\xedvel usa as hip\xf3teses do art. 11 da LGPD, e os demais usam as do art. 7\xba. O cadastro (`POST /api/configuracao/admin/fatos-candidato`, `POST /api/configuracao/admin/fatos-candidato/derivados` ou `POST /api/configuracao/admin/fatos-candidato/agregados`) ou a altera\xe7\xe3o da defini\xe7\xe3o (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`), inclusive a do fato de sistema, juntou uma hip\xf3tese legal e uma classifica\xe7\xe3o que n\xe3o combinam: uma hip\xf3tese s\xf3 do art. 7\xba num fato `SENSIVEL`, ou uma hip\xf3tese s\xf3 do art. 11 num fato de outra classifica\xe7\xe3o.","S\xf3 o art. 7\xba prev\xea `EXECUCAO_CONTRATO`, `INTERESSE_LEGITIMO` e `PROTECAO_DO_CREDITO`; s\xf3 o art. 11 prev\xea `PREVENCAO_A_FRAUDE`. As demais hip\xf3teses existem nos dois artigos.","A recusa vem na lista `errors` da resposta, com `field` igual a `hipoteseLegal`. Ela s\xf3 \xe9 dada quando a classifica\xe7\xe3o e a hip\xf3tese s\xe3o do vocabul\xe1rio: uma delas fora do vocabul\xe1rio recebe a recusa pr\xf3pria ([classifica\xe7\xe3o fora do vocabul\xe1rio](/erros/uniplus.configuracao.fato_candidato.classificacao_protecao_invalida) ou [hip\xf3tese legal fora do vocabul\xe1rio](/erros/uniplus.configuracao.fato_candidato.hipotese_legal_invalida)). Nada \xe9 gravado."],"comoResolver":["Escolha uma hip\xf3tese que caiba na classifica\xe7\xe3o: para `SENSIVEL`, qualquer uma menos `EXECUCAO_CONTRATO`, `INTERESSE_LEGITIMO` e `PROTECAO_DO_CREDITO`; para `PUBLICO`, `INTERNO`, `PESSOAL` e `IDENTIFICADOR`, qualquer uma menos `PREVENCAO_A_FRAUDE`. Se \xe9 a classifica\xe7\xe3o que est\xe1 errada, corrija-a: um dado que revela origem racial ou sa\xfade \xe9 `SENSIVEL`."],"ondeAparece":["Cadastro de um fato do cat\xe1logo (declarado, derivado ou resumo de grupo)","Altera\xe7\xe3o da defini\xe7\xe3o de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);